import subprocess

def run_command(command, timeout=10):
    try:
        result = subprocess.run(command, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
        return result.stdout.decode('utf-8')
    except subprocess.TimeoutExpired:
        print(f"Command '{command}' timed out after {timeout} seconds.")
        return None
    except subprocess.CalledProcessError as e:
        print(f"Command '{command}' failed with exit code {e.returncode}:")
        print(e.stderr.decode('utf-8'))
        return None

def update_and_upgrade():
    update_command = "sudo apt update"
    upgrade_command = "sudo apt upgrade -y"

    print("Running 'apt update'...")
    update_output = run_command(update_command)
    if update_output:
        print("Update output:")
        print(update_output)

    print("\nRunning 'apt upgrade'...")
    upgrade_output = run_command(upgrade_command)
    if upgrade_output:
        print("Upgrade output:")
        print(upgrade_output)

if __name__ == "__main__":
    update_and_upgrade()
